// Get the Hugging Face response
const hfResponse = items[0].json;

// Initialize extracted data object
let extractedData = {
  job_titles: ["Software Developer", "Software Engineer", "Full Stack Developer"],
  skills: ["JavaScript", "Python", "React", "Node.js", "SQL"],
  experience_years: "2",
  location: "Remote"
};

try {
  // Check if we have the expected response structure
  if (Array.isArray(hfResponse) && hfResponse.length > 0) {
    // If response is array, process first item
    const result = hfResponse[0];

    if (result.scores && result.labels) {
      // Extract job titles from high-confidence predictions
      extractedData.job_titles = result.labels
        .filter((label, index) => result.scores[index] > 0.5)
        .slice(0, 3);

      if (extractedData.job_titles.length === 0) {
        extractedData.job_titles = result.labels.slice(0, 3);
      }
    }
  }

  // Try to extract skills from the original resume text
  // This is a fallback approach
  const resumeText = items[0].json.data?.toString() || 
                    items[0].json.toString() || "";

  // Common programming skills to search for
  const commonSkills = [
    "JavaScript", "Python", "Java", "C++", "C#", "PHP", "Ruby", "Go",
    "React", "Vue", "Angular", "Node.js", "Express", "Django", "Flask",
    "SQL", "MongoDB", "PostgreSQL", "MySQL", "Firebase",
    "HTML", "CSS", "Git", "Docker", "Kubernetes", "AWS", "Azure", "GCP",
    "REST API", "GraphQL", "Linux", "Windows", "MacOS"
  ];

  const foundSkills = [];
  commonSkills.forEach(skill => {
    if (resumeText.toLowerCase().includes(skill.toLowerCase())) {
      foundSkills.push(skill);
    }
  });

  if (foundSkills.length > 0) {
    extractedData.skills = foundSkills.slice(0, 5);
  }

  // Try to extract years of experience
  const expMatch = resumeText.match(/(\d+)\s*(?:years?|yrs?)\s*(?:of\s*)?(?:experience|exp)/i);
  if (expMatch) {
    extractedData.experience_years = expMatch[1];
  }

  // Try to extract location
  const locations = ["Remote", "New York", "San Francisco", "London", "Toronto", "Sydney", "India", "USA", "UK"];
  const foundLocation = locations.find(loc => 
    resumeText.toLowerCase().includes(loc.toLowerCase())
  );

  if (foundLocation) {
    extractedData.location = foundLocation;
  }

} catch (error) {
  console.error("Error parsing Hugging Face response:", error);
  // Return default values if parsing fails
}

// Return the formatted data
return [{ json: extractedData }];

// n8n Code node (JavaScript)
// Assumes the input contains something like: items[0].json.jobs_results (array)
// Adjust the path if your jobs array is deeper (see notes below)

// Inspect incoming items structure (for debugging in n8n UI console)
// console.log(JSON.stringify(items, null, 2));

const input = items[0]?.json ?? {};
// Try several common keys just in case the structure differs:
const candidates = [
  input.jobs_results,
  input.jobs,
  input.jobs_results?.jobs_results, // sometimes nested
  input.jobs_results?.results
];
let jobsArray = undefined;
for (const c of candidates) {
  if (Array.isArray(c)) { jobsArray = c; break; }
}

// If still undefined, try to find any array value in the input that looks like jobs
if (!jobsArray) {
  for (const key of Object.keys(input)) {
    if (Array.isArray(input[key])) {
      // naive heuristic: array of objects -> could be jobs
      if (input[key].length === 0 || typeof input[key][0] === 'object') {
        jobsArray = input[key];
        break;
      }
    }
  }
}

// Safe fallback
if (!Array.isArray(jobsArray)) {
  jobsArray = [];
}

// Build formattedJobs (example: extract title, company, location, url if present)
const formattedJobs = jobsArray.map(job => {
  // adapt these keys to match your job object structure
  const title = job.title || job.job_title || job.position || 'Untitled';
  const company = job.company || job.employer || job.hiring_organization || 'Unknown';
  const location = job.location || job.city || job.place || '';
  const url = job.url || job.link || job.job_link || '';

  return {
    title,
    company,
    location,
    url,
    raw: job // keep full raw object for later debugging
  };
});

const result = {
  hasJobs: formattedJobs.length > 0,
  jobCount: formattedJobs.length,
  formattedJobs: formattedJobs.length ? formattedJobs : "No jobs found matching your profile. Try again tomorrow!",
  message: formattedJobs.length ? `${formattedJobs.length} jobs found` : "No jobs found"
};

// Return ONE item (Run Once for All Items). If you prefer one output per input item you must
// build and return an array of items accordingly.
return [{ json: result }];
